ent;border-right: 0px solid transparent;border-bottom: 0px solid transparent;\"><!--<![endif]-->\n  \n<table style=\"font-family:arial,helvetica,sans-serif;\" role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" width=\"100%\" border=\"0\">\n  <tbody>\n    <tr>\n      <td style=\"overflow-wrap:break-word;word-break:break-word;padding:10px;font-family:arial,helvetica,sans-serif;\" align=\"left\">\n        \n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\n  <tr>\n    <td style=\"padding-right: 0px;padding-left: 0px;\" align=\"left\">\n      \n      <img align=\"left\" border=\"0\" src=\"https://www.fs-hirondelle.de/images/logo_hirondelle.png\" alt=\"\" title=\"\" style=\"outline: none;text-decoration: none;-ms-interpolation-mode: bicubic;clear: both;display: inline-block !important;border: none;height: auto;float: none;width: 100%;max-width: 100%;\" width=\"100\"/>\n      \n    </td>\n  </tr>\n</table>\n\n      </td>\n    </tr>\n  </tbody>\n</table>\n\n  <!--[if (!mso)&(!IE)]><!--></div><!--<![endif]-->\n  </div>\n</div>\n<!--[if (mso)|(IE)]></td></tr></table></td><![endif]-->\n      <!--[if (mso)|(IE)]></tr></table></td></tr></table><![endif]-->\n    </div>\n  </div>\n</div>\n\n\n\n\n\n<div class=\"u-row-container\" style=\"padding: 0px;background-color: #ffffff;\">\n  <div class=\"u-row\" style=\"margin: 0 auto;min-width: 320px;max-width: 500px;overflow-wrap: break-word;word-wrap: break-word;word-break: break-word;background-color: transparent;\">\n    <div style=\"border-collapse: collapse;display: table;width: 100%;height: 100%;background-color: transparent;\">\n      <!--[if (mso)|(IE)]><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"padding: 0px;background-color: #ffffff;\"><table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\"><tr style=\"background-color: transparent;\"><![endif]-->\n      \n<!--[if (mso)|(IE)]><td align=\"center\" width=\"500\" style=\"background-color: #ffffff;width: 500px;border-top: 0px solid transparent;border-left: 0px solid transparent;border-right: 0px solid transparent;border-bottom: 0px solid transparent;\" valign=\"top\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"padding: 0px;\"><![endif]-->\n<div class=\"u-col u-col-100\" style=\"max-width: 320px;min-width: 500px;display: table-cell;vertical-align: top;\">\n  <div style=\"background-color: #ffffff;height: 100%;width: 100% !important;\">\n  <!--[if (!mso)&(!IE)]><!--><div style=\"box-sizing: border-box; height: 100%; padding: 0px;border-top: 0px solid transparent;border-left: 0px solid transparent;border-right: 0px solid transparent;border-bottom: 0px solid transparent;\"><!--<![endif]-->\n  \n<table style=\"font-family:arial,helvetica,sans-serif;\" role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" width=\"100%\" border=\"0\">\n  <tbody>\n    <tr>\n      <td style=\"overflow-wrap:break-word;word-break:break-word;padding:10px;font-family:arial,helvetica,sans-serif;\" align=\"left\">\n        \n  <div style=\"font-size: 14px; color: #333333; line-height: 140%; text-align: left; word-wrap: break-word;\">\n    <p style=\"font-size: 18px; color: #3d8ebb; font-weight: bold;\">Hallo {subtag:name|part:first|ucfirst},</p><p style=\"font-size: 16px; margin-top: 15px;\">am Mittwoch, 7.8.24 sind wir wieder von 16 - 19 Uhr für euch in der Flugschule in Weinheim. Wer was braucht oder quatschen will, schaut gerne vorbei. <strong>Meldet euch bitte vorab bei uns per E-Mail mit eurer Wunschuhrzeit an</strong>, damit wir das ein bissel koordinieren können und nicht alle auf einmal dastehen :-).</p>\n  </div>\n\n      </td>\n    </tr>\n  </tbody>\n</table>\n\n  <!--[if (!mso)&(!IE)]><!--></div><!--<![endif]-->\n  </div>\n</div>\n<!--[if (mso)|(IE)]></td></tr></table></td><![endif]-->\n      <!--[if (mso)|(IE)]></tr></table></td></tr></table><![endif]-->\n    </div>\n  </div>\n</div>\n\n\n\n\n\n<div class=\"u-row-container\" style=\"padding: 0px;background-color: #ffffff;\">\n  <div class=\"u-row\" style=\"margin: 0 auto;min-width: 320px;max-width: 500px;overflow-wrap: break-word;word-wrap: break-word;word-break: break-word;background-color: transparent;\">\n    <div style=\"border-collapse: collapse;display: table;width: 100%;height: 100%;background-color: transparent;\">\n      <!--[if (mso)|(IE)]><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"padding: 0px;background-color: #ffffff;\"><table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\"><tr style=\"background-color: transparent;\"><![endif]-->\n      \n<!--[if (mso)|(IE)]><td align=\"center\" width=\"500\" style=\"background-color: #ffffff;width: 500px;border-top: 0px solid transparent;border-left: 0px solid transparent;border-right: 0px solid transparent;border-bottom: 0px solid transparent;\" valign=\"top\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"padding: 0px;\"><![endif]-->\n<div class=\"u-col u-col-100\" style=\"max-width: 320px;min-width: 500px;display: table-cell;vertical-align: top;\">\n  <div style=\"background-color: #ffffff;height: 100%;width: 100% !important;\">\n  <!--[if (!mso)&(!IE)]><!--><div style=\"box-sizing: border-box; height: 100%; padding: 0px;border-top: 0px solid transparent;border-left: 0px solid transparent;border-right: 0px solid transparent;border-bottom: 0px solid transparent;\"><!--<![endif]-->\n  \n<table style=\"font-family:arial,helvetica,sans-serif;\" role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" width=\"100%\" border=\"0\">\n  <tbody>\n    <tr>\n      <td style=\"overflow-wrap:break-word;word-break:break-word;padding:10px;font-family:arial,helvetica,sans-serif;\" align=\"left\">\n        \n  <div style=\"font-size: 14px; color: #333333; line-height: 140%; text-align: left; word-wrap: break-word;\">\n    <p style=\"font-size: 16px; font-style: italic;\">Bitte in den umliegenden Straßen parken, die Parkplätze im Hof der Flugschule sind den Anwohnern vorbehalten!</p><hr style=\"border: none; border-top: 1px solid #ccc; margin: 15px 0;\"/><p style=\"font-size: 18px; color: #333333; font-weight: bold;\">Advance Lightness endlich bei uns eingetroffen.</p><p style=\"font-size: 16px; margin-top: 10px;\">Wir haben lange auf den Nachfolger des Lightness 3 Liegegurtzeuges von Advance gewartet - nun ist es endlich da.</p>\n  </div>\n\n      </td>\n    </tr>\n  </tbody>\n</table>\n\n<table style=\"font-family:arial,helvetica,sans-serif;\" role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" width=\"100%\" border=\"0\">\n  <tbody>\n    <tr>\n      <td style=\"overflow-wrap:break-word;word-break:break-word;padding:10px;font-family:arial,helvetica,sans-serif;\" align=\"left\">\n        \n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\n  <tr>\n    <td style=\"padding-right: 0px;padding-left: 0px;\" align=\"center\">\n      \n      <img align=\"center\" border=\"0\" src=\"http://localhost:5556/uploads/lightness-advance.png\" alt=\"\" title=\"\" style=\"outline: none;text-decoration: none;-ms-interpolation-mode: bicubic;clear: both;display: inline-block !important;border: none;height: auto;float: none;width: 100%;max-width: 480px;\" width=\"480\"/>\n      \n    </td>\n  </tr>\n</table>\n\n      </td>\n    </tr>\n  </tbody>\n</table>\n\n  <!--[if (!mso)&(!IE)]><!--></div><!--<![endif]-->\n  </div>\n</div>\n<!--[if (mso)|(IE)]></td></tr></table></td><![endif]-->\n      <!--[if (mso)|(IE)]></tr></table></td></tr></table><![endif]-->\n    </div>\n  </div>\n</div>\n\n\n\n\n\n<div class=\"u-row-container\" style=\"padding: 0px;background-color: #ffffff;\">\n  <div class=\"u-row\" style=\"margin: 0 auto;min-width: 320px;max-width: 500px;overflow-wrap: break-word;word-wrap: break-word;word-break: break-word;background-color: transparent;\">\n    <div style=\"border-collapse: collapse;display: table;width: 100%;height: 100%;background-color: transparent;\">\n      <!--[if (mso)|(IE)]><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"padding: 0px;background-color: #ffffff;\"><table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\"><tr style=\"background-color: transparent;\"><![endif]-->\n      \n<!--[if (mso)|(IE)]><td align=\"center\" width=\"500\" style=\"background-color: #ffffff;width: 500px;border-top: 0px solid transparent;border-left: 0px solid transparent;border-right: 0px solid transparent;border-bottom: 0px solid transparent;\" valign=\"top\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"padding: 0px;\"><![endif]-->\n<div class=\"u-col u-col-100\" style=\"max-width: 320px;min-width: 500px;display: table-cell;vertical-align: top;\">\n  <div style=\"background-color: #ffffff;height: 100%;width: 100% !important;\">\n  <!--[if (!mso)&(!IE)]><!--><div style=\"box-sizing: border-box; height: 100%; padding: 0px;border-top: 0px solid transparent;border-left: 0px solid transparent;border-right: 0px solid transparent;border-bottom: 0px solid transparent;\"><!--<![endif]-->\n  \n<table style=\"font-family:arial,helvetica,sans-serif;\" role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" width=\"100%\" border=\"0\">\n  <tbody>\n    <tr>\n      <td style=\"overflow-wrap:break-word;word-break:break-word;padding:10px;font-family:arial,helvetica,sans-serif;\" align=\"left\">\n        \n  <div style=\"font-size: 14px; color: #333333; line-height: 140%; text-align: left; word-wrap: break-word;\">\n    <p style=\"font-size: 16px;\">Das Lightness 4 überzeugt durch viele kleine, gut durchdachte Details. Die ersten zwei Gurte sind schon draußen unterwegs und wir sind schon sehr gespannt auf das Feedback :-)!</p><p style=\"font-size: 16px; margin-top: 10px;\">Bei interesse gerne melden.</p><hr style=\"border: none; border-top: 1px solid #ccc; margin: 15px 0;\"/><p style=\"font-size: 18px; color: #333333; font-weight: bold;\">Theorieschulung - Grundkurs und A-Schein</p><p style=\"font-size: 16px; margin-top: 10px;\">Morgen am Mittwoch findet die Theorie für Grundkurs und Freitag bzw. Samstag A-Theorie statt. Der Kurs vermittelt euch die notwendigen Grundlagen fürs Fliegen und ist verpflichtend für alle, die zur Höhenflugschulung mit wollen. Der Kurs findet online statt, also ganz bequem von zu Hause aus! Jeder, der aktuell im Grundkurs ist, kann und sollte also daran teilnehmen :-) Hier geht\'s zur Anmeldung:</p><ul style=\"font-size: 16px; padding-left: 20px; margin-top: 10px;\"><li style=\"margin-bottom: 8px;\"><strong>GK-Theorie</strong> Mittwoch, 7.8.24 18-21 Uhr online: <a href=\"https://www.fs-hirondelle.de/terminkalender/kalenderliste/event/11-grundkurs/1261-gk-th\" style=\"color: #3d8ebb;\">https://www.fs-hirondelle.de/terminkalender/kalenderliste/event/11-grundkurs/1261-gk-th</a></li><li><strong>A-Theorie</strong> 9./10.8.24 Freitag Abend und Samstag ganztägig online: <a href=\"https://www.fs-hirondelle.de/terminkalender/kalenderliste/event/12-hoehenflugschulung/1265-a-theorie\" style=\"color: #3d8ebb;\">https://www.fs-hirondelle.de/terminkalender/kalenderliste/event/12-hoehenflugschulung/1265-a-theorie</a></li></ul>\n  </div>\n\n      </td>\n    </tr>\n  </tbody>\n</table>\n\n  <!--[if (!mso)&(!IE)]><!--></div><!--<![endif]-->\n  </div>\n</div>\n<!--[if (mso)|(IE)]></td></tr></table></td><![endif]-->\n      <!--[if (mso)|(IE)]></tr></table></td></tr></table><![endif]-->\n    </div>\n  </div>\n</div>\n\n\n\n\n\n<div class=\"u-row-container\" style=\"padding: 0px;background-color: #ffffff;\">\n  <div class=\"u-row\" style=\"margin: 0 auto;min-width: 320px;max-width: 500px;overflow-wrap: break-word;word-wrap: break-word;word-break: break-word;background-color: transparent;\">\n    <div style=\"border-collapse: collapse;display: table;width: 100%;height: 100%;background-color: transparent;\">\n      <!--[if (mso)|(IE)]><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"padding: 0px;background-color: #ffffff;\"><table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" width=\"100%\"><tr style=\"background-color: transparent;\"><![endif]-->\n      \n<!--[if (mso)|(IE)]><td align=\"center\" width=\"500\" style=\"background-color: #ffffff;width: 500px;border-top: 0px solid transparent;border-left: 0px solid transparent;border-right: 0px solid transparent;border-bottom: 0px solid transparent;\" valign=\"top\"><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"padding: 0px;\"><![endif]-->\n<div class=\"u-col u-col-100\" style=\"max-width: 320px;min-width: 500px;display: table-cell;vertical-align: top;\">\n  <div style=\"background-color: #ffffff;height: 100%;width: 100% !important;\">\n  <!--[if (!mso)&(!IE)]><!--><div style=\"box-sizing: border-box; height: 100%; padding: 0px;border-top: 0px solid transparent;border-left: 0px solid transparent;border-right: 0px solid transparent;border-bottom: 0px solid transparent;\"><!--<![endif]-->\n  \n<table style=\"font-family:arial,helvetica,sans-serif;\" role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" width=\"100%\" border=\"0\">\n  <tbody>\n    <tr>\n      <td style=\"overflow-wrap:break-word;word-break:break-word;padding:10px;font-family:arial,helvetica,sans-serif;\" align=\"left\">\n        \n  <div style=\"font-size: 14px; color: #333333; line-height: 140%; text-align: left; word-wrap: break-word;\">\n    <p style=\"font-size: 16px;\">Und hier gibt\'s noch weitere freie Plätze bei unseren Reisen und Trainings:</p><ul style=\"font-size: 16px; padding-left: 20px; margin-top: 10px;\"><li style=\"margin-bottom: 8px;\">Sicherheitstraining am Gardasee 1.9. - 6.9.2024 <a href=\"https://www.fs-hirondelle.de/terminkalender/kalenderliste/event/15-performance-training/1284-sicherheitstraining\" style=\"color: #3d8ebb;\">https://www.fs-hirondelle.de/terminkalender/kalenderliste/event/15-performance-training/1284-sicherheitstraining</a></li><li>Südafrika-Safari 11.-25.1.2025 <a href=\"https://www.fs-hirondelle.de/terminkalender/kalenderliste/event/14-reisen/1286-s%C3%BCdafrika-tour\" style=\"color: #3d8ebb;\">https://www.fs-hirondelle.de/terminkalender/kalenderliste/event/14-reisen/1286-südafrika-tour</a></li></ul><p style=\"font-size: 16px; margin-top: 15px;\">…mehr Infos rund ums\'s Gleitschirmfliegen, zu unseren Kursen und Reisen findet ihr auf unserer Website <a href=\"https://www.fs-hirondelle.de\" style=\"color: #3d8ebb;\">www.fs-hirondelle.de</a> sowie in unserem <a href=\"#\" style=\"color: #3d8ebb;\">YouTube-Kanal</a> - schaut einfach mal rein!</p><p style=\"font-size: 16px; color: #3d8ebb; font-style: italic; font-weight: bold; margin-top: 20px;\">Luftige Grüße<br>Team Hirondelle</p>\n  </div>\n\n      </td>\n    </tr>\n  </tbody>\n</table>\n\n  <!--[if (!mso)&(!IE)]><!--></div><!--<![endif]-->\n  </div>\n</div>\n<!--[if (mso)|(IE)]></td></tr></table></td><![endif]-->\n      <!--[if (mso)|(IE)]></tr></table></td></tr></table><![endif]-->\n    </div>\n  </div>\n</div>\n\n\n\n\n\n<div class=\"u-row-container\" style=\"padding: 0px;background-color: #ffffff;\">\n  <div class=\"u-row\" style=\"margin: 0 auto;min-width: 320px;max-width: 500px;overflow-wrap: break-word;word-wrap: break-word;word-break: break-word;background-color: transparent;\">\n    <div style=\"border-collapse: collapse;display: table;width: 100%;height: 100%;background-color: transparent;\">\n      <!--[if (mso)|(IE)]><table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\"><tr><td style=\"padding: 0px;background-color: #ffffff;\"><table role=\"presentation\" cellpadding=\"0\" cellspaci