eDesktop\":false,\"_meta\":{\"htmlID\":\"u_row_3\",\"htmlClassNames\":\"u_row\"},\"selectable\":true,\"draggable\":true,\"duplicatable\":true,\"deletable\":true,\"hideable\":true,\"locked\":false}},{\"id\":\"t0D07oeHed\",\"cells\":[1],\"columns\":[{\"id\":\"V-OXAtsRX6\",\"contents\":[{\"id\":\"RWMqz_R7r-\",\"type\":\"text\",\"values\":{\"containerPadding\":\"10px\",\"anchor\":\"\",\"fontSize\":\"14px\",\"color\":\"#333333\",\"textAlign\":\"left\",\"lineHeight\":\"140%\",\"linkStyle\":{\"inherit\":true,\"linkColor\":\"#0000ee\",\"linkHoverColor\":\"#0000ee\",\"linkUnderline\":true,\"linkHoverUnderline\":true},\"hideDesktop\":false,\"displayCondition\":null,\"_styleGuide\":null,\"_meta\":{\"htmlID\":\"u_content_text_1\",\"htmlClassNames\":\"u_content_text\"},\"selectable\":true,\"draggable\":true,\"duplicatable\":true,\"deletable\":true,\"hideable\":true,\"locked\":false,\"text\":\"<p style=\\\"font-size: 18px; color: #3d8ebb; font-weight: bold;\\\">Hallo {subtag:name|part:first|ucfirst},</p><p style=\\\"font-size: 16px; margin-top: 15px;\\\">am Mittwoch, 7.8.24 sind wir wieder von 16 - 19 Uhr für euch in der Flugschule in Weinheim. Wer was braucht oder quatschen will, schaut gerne vorbei. <strong>Meldet euch bitte vorab bei uns per E-Mail mit eurer Wunschuhrzeit an</strong>, damit wir das ein bissel koordinieren können und nicht alle auf einmal dastehen :-).</p>\",\"padding\":\"20px\"},\"hasDeprecatedFontControls\":true}],\"values\":{\"backgroundColor\":\"#ffffff\",\"_meta\":{\"htmlID\":\"u_column_4\",\"htmlClassNames\":\"u_column\"},\"deletable\":true}}],\"values\":{\"displayCondition\":null,\"columns\":false,\"_styleGuide\":null,\"backgroundColor\":\"#ffffff\",\"columnsBackgroundColor\":\"\",\"backgroundImage\":{\"url\":\"\",\"fullWidth\":true,\"repeat\":\"no-repeat\",\"size\":\"custom\",\"position\":\"center\"},\"padding\":\"0px\",\"anchor\":\"\",\"hideDesktop\":false,\"_meta\":{\"htmlID\":\"u_row_4\",\"htmlClassNames\":\"u_row\"},\"selectable\":true,\"draggable\":true,\"duplicatable\":true,\"deletable\":true,\"hideable\":true,\"locked\":false}},{\"id\":\"rz1vbKcN3h\",\"cells\":[1],\"columns\":[{\"id\":\"PkkSdkq3fS\",\"contents\":[{\"id\":\"IOsZ4btaP-\",\"type\":\"text\",\"values\":{\"containerPadding\":\"10px\",\"anchor\":\"\",\"fontSize\":\"14px\",\"color\":\"#333333\",\"textAlign\":\"left\",\"lineHeight\":\"140%\",\"linkStyle\":{\"inherit\":true,\"linkColor\":\"#0000ee\",\"linkHoverColor\":\"#0000ee\",\"linkUnderline\":true,\"linkHoverUnderline\":true},\"hideDesktop\":false,\"displayCondition\":null,\"_styleGuide\":null,\"_meta\":{\"htmlID\":\"u_content_text_2\",\"htmlClassNames\":\"u_content_text\"},\"selectable\":true,\"draggable\":true,\"duplicatable\":true,\"deletable\":true,\"hideable\":true,\"locked\":false,\"text\":\"<p style=\\\"font-size: 16px; font-style: italic;\\\">Bitte in den umliegenden Straßen parken, die Parkplätze im Hof der Flugschule sind den Anwohnern vorbehalten!</p><hr style=\\\"border: none; border-top: 1px solid #ccc; margin: 15px 0;\\\"/><p style=\\\"font-size: 18px; color: #333333; font-weight: bold;\\\">Advance Lightness endlich bei uns eingetroffen.</p><p style=\\\"font-size: 16px; margin-top: 10px;\\\">Wir haben lange auf den Nachfolger des Lightness 3 Liegegurtzeuges von Advance gewartet - nun ist es endlich da.</p>\",\"padding\":\"20px\"},\"hasDeprecatedFontControls\":true},{\"id\":\"2CxyaqQHHv\",\"type\":\"image\",\"values\":{\"containerPadding\":\"10px\",\"anchor\":\"\",\"src\":{\"url\":\"http://localhost:5556/uploads/lightness-advance.png\",\"width\":560,\"height\":\"auto\"},\"textAlign\":\"center\",\"altText\":\"\",\"action\":{\"name\":\"web\",\"values\":{\"href\":\"\",\"target\":\"_blank\"}},\"hideDesktop\":false,\"displayCondition\":null,\"_styleGuide\":null,\"_meta\":{\"htmlID\":\"u_content_image_3\",\"htmlClassNames\":\"u_content_image\"},\"selectable\":true,\"draggable\":true,\"duplicatable\":true,\"deletable\":true,\"hideable\":true,\"locked\":false,\"padding\":\"0px 20px 20px 20px\"}}],\"values\":{\"backgroundColor\":\"#ffffff\",\"_meta\":{\"htmlID\":\"u_column_5\",\"htmlClassNames\":\"u_column\"},\"deletable\":true}}],\"values\":{\"displayCondition\":null,\"columns\":false,\"_styleGuide\":null,\"backgroundColor\":\"#ffffff\",\"columnsBackgroundColor\":\"\",\"backgroundImage\":{\"url\":\"\",\"fullWidth\":true,\"repeat\":\"no-repeat\",\"size\":\"custom\",\"position\":\"center\"},\"padding\":\"0px\",\"anchor\":\"\",\"hideDesktop\":false,\"_meta\":{\"htmlID\":\"u_row_5\",\"htmlClassNames\":\"u_row\"},\"selectable\":true,\"draggable\":true,\"duplicatable\":true,\"deletable\":true,\"hideable\":true,\"locked\":false}},{\"id\":\"jFzY5zlWHl\",\"cells\":[1],\"columns\":[{\"id\":\"s8wJEfztpA\",\"contents\":[{\"id\":\"V8iiwT2D3V\",\"type\":\"text\",\"values\":{\"containerPadding\":\"10px\",\"anchor\":\"\",\"fontSize\":\"14px\",\"color\":\"#333333\",\"textAlign\":\"left\",\"lineHeight\":\"140%\",\"linkStyle\":{\"inherit\":true,\"linkColor\":\"#0000ee\",\"linkHoverColor\":\"#0000ee\",\"linkUnderline\":true,\"linkHoverUnderline\":true},\"hideDesktop\":false,\"displayCondition\":null,\"_styleGuide\":null,\"_meta\":{\"htmlID\":\"u_content_text_3\",\"htmlClassNames\":\"u_content_text\"},\"selectable\":true,\"draggable\":true,\"duplicatable\":true,\"deletable\":true,\"hideable\":true,\"locked\":false,\"text\":\"<p style=\\\"font-size: 16px;\\\">Das Lightness 4 überzeugt durch viele kleine, gut durchdachte Details. Die ersten zwei Gurte sind schon draußen unterwegs und wir sind schon sehr gespannt auf das Feedback :-)!</p><p style=\\\"font-size: 16px; margin-top: 10px;\\\">Bei interesse gerne melden.</p><hr style=\\\"border: none; border-top: 1px solid #ccc; margin: 15px 0;\\\"/><p style=\\\"font-size: 18px; color: #333333; font-weight: bold;\\\">Theorieschulung - Grundkurs und A-Schein</p><p style=\\\"font-size: 16px; margin-top: 10px;\\\">Morgen am Mittwoch findet die Theorie für Grundkurs und Freitag bzw. Samstag A-Theorie statt. Der Kurs vermittelt euch die notwendigen Grundlagen fürs Fliegen und ist verpflichtend für alle, die zur Höhenflugschulung mit wollen. Der Kurs findet online statt, also ganz bequem von zu Hause aus! Jeder, der aktuell im Grundkurs ist, kann und sollte also daran teilnehmen :-) Hier geht\'s zur Anmeldung:</p><ul style=\\\"font-size: 16px; padding-left: 20px; margin-top: 10px;\\\"><li style=\\\"margin-bottom: 8px;\\\"><strong>GK-Theorie</strong> Mittwoch, 7.8.24 18-21 Uhr online: <a href=\\\"https://www.fs-hirondelle.de/terminkalender/kalenderliste/event/11-grundkurs/1261-gk-th\\\" style=\\\"color: #3d8ebb;\\\">https://www.fs-hirondelle.de/terminkalender/kalenderliste/event/11-grundkurs/1261-gk-th</a></li><li><strong>A-Theorie</strong> 9./10.8.24 Freitag Abend und Samstag ganztägig online: <a href=\\\"https://www.fs-hirondelle.de/terminkalender/kalenderliste/event/12-hoehenflugschulung/1265-a-theorie\\\" style=\\\"color: #3d8ebb;\\\">https://www.fs-hirondelle.de/terminkalender/kalenderliste/event/12-hoehenflugschulung/1265-a-theorie</a></li></ul>\",\"padding\":\"20px\"},\"hasDeprecatedFontControls\":true}],\"values\":{\"backgroundColor\":\"#ffffff\",\"_meta\":{\"htmlID\":\"u_column_6\",\"htmlClassNames\":\"u_column\"},\"deletable\":true}}],\"values\":{\"displayCondition\":null,\"columns\":false,\"_styleGuide\":null,\"backgroundColor\":\"#ffffff\",\"columnsBackgroundColor\":\"\",\"backgroundImage\":{\"url\":\"\",\"fullWidth\":true,\"repeat\":\"no-repeat\",\"size\":\"custom\",\"position\":\"center\"},\"padding\":\"0px\",\"anchor\":\"\",\"hideDesktop\":false,\"_meta\":{\"htmlID\":\"u_row_6\",\"htmlClassNames\":\"u_row\"},\"selectable\":true,\"draggable\":true,\"duplicatable\":true,\"deletable\":true,\"hideable\":true,\"locked\":false}},{\"id\":\"c6c_R0pj1B\",\"cells\":[1],\"columns\":[{\"id\":\"X3r6vbixwj\",\"contents\":[{\"id\":\"duGzt11KFV\",\"type\":\"text\",\"values\":{\"containerPadding\":\"10px\",\"anchor\":\"\",\"fontSize\":\"14px\",\"color\":\"#333333\",\"textAlign\":\"left\",\"lineHeight\":\"140%\",\"linkStyle\":{\"inherit\":true,\"linkColor\":\"#0000ee\",\"linkHoverColor\":\"#0000ee\",\"linkUnderline\":true,\"linkHoverUnderline\":true},\"hideDesktop\":false,\"displayCondition\":null,\"_styleGuide\":null,\"_meta\":{\"htmlID\":\"u_content_text_4\",\"htmlClassNames\":\"u_content_text\"},\"selectable\":true,\"draggable\":true,\"duplicatable\":true,\"deletable\":true,\"hideable\":true,\"locked\":false,\"text\":\"<p style=\\\"font-size: 16px;\\\">Und hier gibt\'s noch weitere freie Plätze bei unseren Reisen und Trainings:</p><ul style=\\\"font-size: 16px; padding-left: 20px; margin-top: 10px;\\\"><li style=\\\"margin-bottom: 8px;\\\">Sicherheitstraining am Gardasee 1.9. - 6.9.2024 <a href=\\\"https://www.fs-hirondelle.de/terminkalender/kalenderliste/event/15-performance-training/1284-sicherheitstraining\\\" style=\\\"color: #3d8ebb;\\\">https://www.fs-hirondelle.de/terminkalender/kalenderliste/event/15-performance-training/1284-sicherheitstraining</a></li><li>Südafrika-Safari 11.-25.1.2025 <a href=\\\"https://www.fs-hirondelle.de/terminkalender/kalenderliste/event/14-reisen/1286-s%C3%BCdafrika-tour\\\" style=\\\"color: #3d8ebb;\\\">https://www.fs-hirondelle.de/terminkalender/kalenderliste/event/14-reisen/1286-südafrika-tour</a></li></ul><p style=\\\"font-size: 16px; margin-top: 15px;\\\">…mehr Infos rund ums\'s Gleitschirmfliegen, zu unseren Kursen und Reisen findet ihr auf unserer Website <a href=\\\"https://www.fs-hirondelle.de\\\" style=\\\"color: #3d8ebb;\\\">www.fs-hirondelle.de</a> sowie in unserem <a href=\\\"#\\\" style=\\\"color: #3d8ebb;\\\">YouTube-Kanal</a> - schaut einfach mal rein!</p><p style=\\\"font-size: 16px; color: #3d8ebb; font-style: italic; font-weight: bold; margin-top: 20px;\\\">Luftige Grüße<br>Team Hirondelle</p>\",\"padding\":\"20px\"},\"hasDeprecatedFontControls\":true}],\"values\":{\"backgroundColor\":\"#ffffff\",\"_meta\":{\"htmlID\":\"u_column_7\",\"htmlClassNames\":\"u_column\"},\"deletable\":true}}],\"values\":{\"displ